 29→import { useStages, useUpdateStage, useStageSummary, STAGE_ORDER, type HiringStage } from "@/hooks/useStageTracker";
 30→
 31→interface JobDetailViewProps {
 32→  selectedJobId: string | null;
 33→  selectedJob: PastJob | null;
 34→  results: Result[];
 35→  setResults: (results: Result[] | ((prev: Result[]) => Result[])) => void;
 36→  existingResumes: ExistingResume[];
 37→  setExistingResumes: (resumes: ExistingResume[] | ((prev: ExistingResume[]) => ExistingResume[])) => void;
 38→  onJobCreated: (job: PastJob) => void;
 39→  onAuthRequired: () => void;
 40→  onJobUpdated?: (jobId: string, updates: Partial<PastJob>) => void;
 41→  isAuthenticated?: boolean;
 42→}
 43→
 44→interface UploadedFile {
 45→  file: File;
 46→  name: string;
 47→}
 48→
 49→const UUID_REGEX = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
 50→
 51→const JobDetailView = ({
 52→  selectedJobId,
 53→  selectedJob,
 54→  results,
 55→  setResults,
 56→  existingResumes,
 57→  setExistingResumes,
 58→  onJobCreated,
 59→  onAuthRequired,
 60→  onJobUpdated,
 61→  isAuthenticated = true,
 62→}: JobDetailViewProps) => {
 63→  const { user, profile, refreshProfile } = useAuth();
 64→  const { data: config } = usePlatformConfig();
 65→
 66→  const [jobDescription, setJobDescription] = useState("");
 67→  const [files, setFiles] = useState<UploadedFile[]>([]);
 68→  const [ranking, setRanking] = useState(false);
 69→  const [rankingProgress, setRankingProgress] = useState(0);
 70→  const [scoredCount, setScoredCount] = useState(0);
 71→  const [totalToScore, setTotalToScore] = useState(0);
 72→  const [expandedRows, setExpandedRows] = useState<Set<string>>(new Set());
 73→  const [dragOver, setDragOver] = useState(false);
 74→  const [rankingError, setRankingError] = useState<{ type: "credits" | "rate_limit" | "generic"; message: string } | null>(null);
 75→  const [validationErrors, setValidationErrors] = useState<string[]>([]);
 76→  const [selectedResumes, setSelectedResumes] = useState<Set<string>>(new Set());
 77→  const [deleteConfirm, setDeleteConfirm] = useState<{type: "single" | "bulk"; resumeId?: string; filePath?: string | null;} | null>(null);
 78→  const [deleting, setDeleting] = useState(false);
 79→  const [analyzingJd, setAnalyzingJd] = useState(false);
 80→  const [dismissedResumes, setDismissedResumes] = useState<Set<string>>(() => new Set());
 81→  const [showArchived, setShowArchived] = useState(false);
 82→  const [stageFilter, setStageFilter] = useState<HiringStage | null>(null);
 83→  const [jdRewriteOpen, setJdRewriteOpen] = useState(false);
 84→  const [stuckJobDetected, setStuckJobDetected] = useState(false);
 85→  const [retrying, setRetrying] = useState(false);
 86→
 87→  const resultsRef = useRef<HTMLDivElement>(null);
 88→  const rankingFilesRef = useRef<Set<string>>(new Set());
 89→  const activeJobRef = useRef<string | null>(selectedJobId);
 90→  const maxResumes = config?.max_resumes_per_job ?? 10;
 91→  const maxFileSizeMb = config?.max_file_size_mb ?? 5;
 92→
 93→  const isNewJobMode = selectedJobId === null;
 94→  const isExistingJob = selectedJobId !== null && selectedJob !== null;
 95→
 96→  // Hiring Stage Tracker
 97→  const { data: stages } = useStages(selectedJobId);
 98→  const updateStageMutation = useUpdateStage();
 99→  const stageSummary = useStageSummary(selectedJobId);
100→  const stageMap = new Map((stages ?? []).map((s) => [s.resume_id, s]));

100→  const stageMap = new Map((stages ?? []).map((s) => [s.resume_id, s]));
101→
102→  const handleStageChange = (resumeId: string, newStage: HiringStage) => {
103→    if (!selectedJobId) return;
104→    const current = stageMap.get(resumeId);
105→    updateStageMutation.mutate({
106→      resumeId,
107→      jobId: selectedJobId,
108→      newStage,
109→      currentStage: current?.stage,
110→    });
111→  };
112→
113→  const formatCandidateName = (filename: string) => {
114→    const name = filename.replace(/\.\w+$/, "");
115→    if (UUID_REGEX.test(name)) return `Resume ${name.slice(0, 6).toUpperCase()}`;
116→    return name.replace(/[-_]/g, " ").replace(/\b\w/g, (c) => c.toUpperCase());
117→  };
118→
119→  // Merge unranked resumes
120→  const resultResumeIds = new Set(results.map((r) => r.resume_id));
121→  const pendingResumes: Result[] = existingResumes
122→    .filter((r) => !resultResumeIds.has(r.id))
123→    .map((r) => ({
124→      id: `pending-${r.id}`,
125→      resume_id: r.id,
126→      overall_score: 0,
127→      missing_skills: [], summary: null, interview_questions: null,
128→      filename: r.filename, file_path: r.file_path, candidate_name: r.candidate_name,
129→      pending: true,
130→    }));
131→  const allResults = [...results, ...pendingResumes];
132→
133→  // Selection helpers
134→  const toggleSelectResume = (resumeId: string) => {
135→    setSelectedResumes((prev) => {
136→      const next = new Set(prev);
137→      if (next.has(resumeId)) next.delete(resumeId); else next.add(resumeId);
138→      return next;
139→    });
140→  };
141→  const toggleSelectAll = () => {
142→    if (selectedResumes.size === allResults.length) setSelectedResumes(new Set());
143→    else setSelectedResumes(new Set(allResults.map((r) => r.resume_id)));
144→  };
145→
146→  // Delete logic
147→  const deleteResume = async (resumeId: string, filePath: string | null) => {
148→    if (filePath) await supabase.storage.from("resumes").remove([filePath]);
149→    await supabase.from("results").delete().eq("resume_id", resumeId);
150→    await supabase.from("resumes").delete().eq("id", resumeId);
151→    setResults((prev: Result[]) => prev.filter((r) => r.resume_id !== resumeId));
152→    setExistingResumes((prev: ExistingResume[]) => prev.filter((r) => r.id !== resumeId));
153→    setSelectedResumes((prev) => { const next = new Set(prev); next.delete(resumeId); return next; });
154→  };
155→
156→  const handleDeleteConfirm = async () => {
157→    if (!deleteConfirm) return;
158→    setDeleting(true);
159→    try {
160→      if (deleteConfirm.type === "single" && deleteConfirm.resumeId) {
161→        await deleteResume(deleteConfirm.resumeId, deleteConfirm.filePath ?? null);
162→        toast.success("Resume deleted");
163→      } else if (deleteConfirm.type === "bulk") {
164→        const toDelete = allResults.filter((r) => selectedResumes.has(r.resume_id));
165→        for (const r of toDelete) await deleteResume(r.resume_id, r.file_path);
166→        toast.success(`${toDelete.length} resume(s) deleted`);
167→      }
168→    } catch { toast.error("Failed to delete"); }
169→    finally { setDeleting(false); setDeleteConfirm(null); }
170→  };
171→
172→  // File handling
173→  const handleFileDrop = useCallback((e: React.DragEvent) => {
174→    e.preventDefault(); setDragOver(false);
175→    const dropped = Array.from(e.dataTransfer.files).filter(
176→      (f) => f.type === "application/pdf" || f.type === "application/vnd.openxmlformats-officedocument.wordprocessingml.document"
177→    );
178→    addFiles(dropped);
179→  }, [files, maxResumes, maxFileSizeMb]);
180→
181→  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
182→    if (e.target.files) addFiles(Array.from(e.target.files));
183→  };
184→
185→  const addFiles = (newFiles: File[]) => {
186→    const currentCount = isExistingJob ? existingResumes.length + files.length : files.length;
187→    const valid = newFiles.filter((f) => {
188→      if (f.size > maxFileSizeMb * 1024 * 1024) { toast.error(`${f.name} exceeds ${maxFileSizeMb}MB limit`); return false; }
189→      return true;
190→    });
191→    const remaining = maxResumes - currentCount;
192→    if (valid.length > remaining) toast.error(`Max ${maxResumes} resumes per job`);
193→    const toAdd = valid.slice(0, Math.max(0, remaining)).map((f) => ({ file: f, name: f.name }));
194→    setFiles((prev) => [...prev, ...toAdd]);
195→  };
196→
197→  const removeFile = (index: number) => setFiles((prev) => prev.filter((_, i) => i !== index));
198→  const toggleRow = (id: string) => {
199→    setExpandedRows((prev) => { const next = new Set(prev); if (next.has(id)) next.delete(id); else next.add(id); return next; });

200→  };
201→
202→  const copyInboxEmail = () => {
203→    if (profile?.inbox_email) { navigator.clipboard.writeText(profile.inbox_email); toast.success("Inbox email copied!"); }
204→  };
205→
206→  const validate = (): string[] => {
207→    const errors: string[] = [];
208→    if (isNewJobMode && !jobDescription.trim()) errors.push("Job description is required.");
209→    const filesToCheck = files.filter(f => !rankingFilesRef.current.has(f.name));
210→    if (filesToCheck.length === 0) errors.push("Upload at least one resume.");
211→    const splitTotal = (profile?.subscription_credits ?? 0) + (profile?.topup_credits ?? 0);
212→    const totalCredits = splitTotal > 0 ? splitTotal : (profile?.credits ?? 0);
213→    if (user && totalCredits < Math.min(filesToCheck.length, maxResumes)) {
214→      errors.push(`Not enough credits. You need ${Math.min(filesToCheck.length, maxResumes)} but have ${totalCredits}.`);
215→    }
216→    return errors;
217→  };
218→
219→  // ── Analyze JD ──────────────────────────────────────────────
220→  const analyzeJd = async (jobId: string) => {
221→    setAnalyzingJd(true);
222→    try {
223→      const { data, error: invokeError } = await supabase.functions.invoke("analyze-jd", {
224→        body: { job_id: jobId },
225→      });
226→      if (invokeError) throw new Error(invokeError.message || "JD analysis failed");
227→      if (data?.error) throw new Error(data.error);
228→      if (onJobUpdated) {
229→        onJobUpdated(jobId, {
230→          jd_analysis_json: data.jd_analysis,
231→          dynamic_weights_json: data.dynamic_weights,
232→        });
233→      }
234→      return data;
235→    } catch (err: any) {
236→      toast.error(err.message || "JD analysis failed");
237→      throw err;
238→    } finally {
239→      setAnalyzingJd(false);
240→    }
241→  };
242→
243→  // ── Reset all transient state when switching jobs ──
244→  useEffect(() => {
245→    activeJobRef.current = selectedJobId;
246→    setFiles([]);
247→    setRanking(false);
248→    setRankingProgress(0);
249→    setScoredCount(0);
250→    setTotalToScore(0);
251→    setExpandedRows(new Set());
252→    setValidationErrors([]);
253→    setRankingError(null);
254→    setAnalyzingJd(false);
255→    setStuckJobDetected(false);
256→    setSelectedResumes(new Set());
257→    setShowArchived(false);
258→    setStageFilter(null);
259→    rankingFilesRef.current = new Set();
260→    autoRankTriggered.current = false;
261→    if (selectedJobId) {
262→      try {
263→        const stored = localStorage.getItem(`dismissed_${selectedJobId}`);
264→        if (stored) {
265→          setDismissedResumes(new Set(JSON.parse(stored) as string[]));
266→        } else {
267→          setDismissedResumes(new Set());
268→        }
269→      } catch {
270→        setDismissedResumes(new Set());
271→      }
272→    } else {
273→      setDismissedResumes(new Set());
274→    }
275→  }, [selectedJobId]);
276→
277→  // ── Auto-rank ───────────────────────────────────────────────
278→  const autoRankTriggered = useRef(false);
279→  useEffect(() => {
280→    const unrankedFiles = files.filter(f => !rankingFilesRef.current.has(f.name));
281→    if (unrankedFiles.length > 0 && !ranking && !autoRankTriggered.current) {
282→      if (isNewJobMode && !jobDescription.trim()) return;
283→      autoRankTriggered.current = true;
284→      handleRankClick();
285→    }
286→    if (files.length === 0 && !ranking) autoRankTriggered.current = false;
287→  }, [files, ranking, isNewJobMode, jobDescription]);
288→
289→  const handleRankingError = (err: any) => {
290→    const msg: string = err?.message || "Ranking failed.";
291→    if (msg.includes("Insufficient credits") || err?.status === 402) {
292→      setRankingError({ type: "credits", message: "You don't have enough credits to rank these resumes." });
293→    } else if (msg.includes("Rate limit") || err?.status === 429) {
294→      setRankingError({ type: "rate_limit", message: "Too many jobs in a short time. Please wait a minute and try again." });
295→    } else {
296→      setRankingError({ type: "generic", message: msg });
297→      toast.error(msg);
298→    }
299→  };

300→
301→  const handleRankClick = () => {
302→    if (!user) { onAuthRequired(); return; }
303→    setRankingError(null);
304→    const errors = validate();
305→    setValidationErrors(errors);
306→    if (errors.length > 0) return;
307→    if (isExistingJob) handleRankExisting(); else handleRankNew();
308→  };
309→
310→  const handleRankNew = async () => {
311→    if (!user) return;
312→    const filesToRank = [...files];
313→    rankingFilesRef.current = new Set(filesToRank.map(f => f.name));
314→    setRanking(true); setResults([]); setRankingError(null);
315→    setRankingProgress(5); setScoredCount(0); setTotalToScore(filesToRank.length);
316→
317→    try {
318→      const autoTitle = (() => {
319→        const firstLine = jobDescription.trim().split("\n")[0].trim();
320→        return firstLine.slice(0, 50).trim() || `Job - ${new Date().toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" })}`;
321→      })();
322→
323→      const { data: job, error: jobError } = await supabase
324→        .from("jobs")
325→        .insert({ user_id: user.id, job_description: jobDescription, status: "pending", title: autoTitle } as any)
326→        .select("id, inbox_email")
327→        .single();
328→      if (jobError || !job) throw new Error(jobError?.message || "Failed to create job");
329→      setRankingProgress(10);
330→
331→      const analysisData = await analyzeJd(job.id);
332→      setRankingProgress(25);
333→
334→      onJobCreated({
335→        id: job.id,
336→        title: autoTitle,
337→        job_description: jobDescription,
338→        status: "processing",
339→        created_at: new Date().toISOString(),
340→        resume_count: filesToRank.length,
341→        jd_analysis_json: analysisData.jd_analysis,
342→        dynamic_weights_json: analysisData.dynamic_weights,
343→        inbox_email: job.inbox_email ?? null,
344→      });
345→
346→      const resumeIds = await uploadFilesFromSnapshot(job.id, filesToRank);
347→      setRankingProgress(40);
348→
349→      await rankAndPoll(job.id, resumeIds);
350→
351→      setJobDescription("");
352→      setFiles(prev => prev.filter(f => !rankingFilesRef.current.has(f.name)));
353→      toast.success("Candidates ranked!");
354→    } catch (err: any) {
355→      handleRankingError(err);
356→    } finally {
357→      rankingFilesRef.current = new Set();
358→      setRanking(false); setRankingProgress(0); setScoredCount(0); setTotalToScore(0);
359→      autoRankTriggered.current = false;
360→    }
361→  };
362→
363→  const handleRankExisting = async () => {
364→    if (!user || !selectedJobId) return;
365→    const filesToRank = [...files];
366→    rankingFilesRef.current = new Set(filesToRank.map(f => f.name));
367→    setRanking(true); setRankingError(null);
368→    setRankingProgress(10); setScoredCount(0); setTotalToScore(filesToRank.length);
369→
370→    try {
371→      if (!selectedJob?.jd_analysis_json) {
372→        await analyzeJd(selectedJobId);
373→        setRankingProgress(25);
374→      }
375→
376→      const resumeIds = await uploadFilesFromSnapshot(selectedJobId, filesToRank);
377→      setRankingProgress(40);
378→
379→      await rankAndPoll(selectedJobId, resumeIds);
380→
381→      const { data: allResumes } = await supabase
382→        .from("resumes")
383→        .select("id, filename, file_path, candidate_name, created_at")
384→        .eq("job_id", selectedJobId)
385→        .order("created_at", { ascending: false });
386→      if (allResumes) setExistingResumes(allResumes);
387→
388→      setFiles(prev => prev.filter(f => !rankingFilesRef.current.has(f.name)));
389→      toast.success("New resumes ranked!");
390→    } catch (err: any) {
391→      handleRankingError(err);
392→    } finally {
393→      rankingFilesRef.current = new Set();
394→      setRanking(false); setRankingProgress(0); setScoredCount(0); setTotalToScore(0);
395→      autoRankTriggered.current = false;
396→    }
397→  };
398→
399→  const uploadFilesFromSnapshot = async (jobId: string, filesToUpload: UploadedFile[]): Promise<string[]> => {

400→    if (!user) return [];
401→    const resumeIds: string[] = [];
402→    for (const { file, name } of filesToUpload) {
403→      const filePath = `${user.id}/${jobId}/${Date.now()}_${name}`;
404→      const { error: uploadError } = await supabase.storage.from("resumes").upload(filePath, file);
405→      if (uploadError) throw new Error(`Upload failed: ${uploadError.message}`);
406→      const { data: resume, error: resumeError } = await supabase
407→        .from("resumes")
408→        .insert({ job_id: jobId, filename: name, file_path: filePath })
409→        .select("id")
410→        .single();
411→      if (resumeError || !resume) throw new Error(resumeError?.message || "Failed to save resume");
412→      resumeIds.push(resume.id);
413→    }
414→    return resumeIds;
415→  };
416→
417→  const rankAndPoll = async (jobId: string, resumeIds: string[]) => {
418→    const { data: rankData, error: rankError } = await supabase.functions.invoke("rank-resumes", {
419→      body: { job_id: jobId, resume_ids: resumeIds },
420→    });
421→    if (rankError) {
422→      const err: any = new Error(rankError.message || "Ranking failed");
423→      err.status = 500;
424→      throw err;
425→    }
426→    if (rankData?.error) {
427→      const err: any = new Error(rankData.error);
428→      err.status = rankData.status || 500;
429→      throw err;
430→    }
431→    setRankingProgress(60);
432→
433→    for (let i = 0; i < 150; i++) {
434→      await new Promise((r) => setTimeout(r, 2000));
435→      // Stop polling if user switched to a different job
436→      if (activeJobRef.current !== jobId) return;
437→      const { data: resumeProgress } = await supabase.from("resumes").select("id, status").in("id", resumeIds);
438→      if (resumeProgress) {
439→        const done = resumeProgress.filter((r: any) => r.status === "done" || r.status === "failed").length;
440→        setScoredCount(done);
441→        const pct = resumeIds.length > 0 ? Math.round((done / resumeIds.length) * 35) : 0;
442→        setRankingProgress(Math.min(60 + pct, 95));
443→      }
444→
445→      const { data: jobData } = await supabase.from("jobs").select("status, processing_started_at").eq("id", jobId).single();
446→
447→      // Stuck-job detection: if processing for > 5 minutes
448→      if (jobData?.status === "processing" && jobData?.processing_started_at) {
449→        const elapsed = Date.now() - new Date(jobData.processing_started_at).getTime();
450→        if (elapsed > 5 * 60 * 1000) {
451→          setStuckJobDetected(true);
452→          setRanking(false);
453→          setRankingProgress(0);
454→          return;
455→        }
456→      }
457→
458→      if (jobData?.status === "completed") {
459→         const { data: allResumes } = await supabase.from("resumes").select("id, filename, file_path, candidate_name, parsed_json").eq("job_id", jobId);
460→         if (allResumes) {
461→           const allResumeIds = allResumes.map((r: any) => r.id);
462→            const { data: resultData } = await supabase
463→              .from("results")
464→              .select("id, resume_id, overall_score, missing_skills, summary, interview_questions, hard_fit, category_scores_json, confidence, strengths_json, gaps_json, explanation_json, matched_must_haves, missing_must_haves, scoring_version")
465→              .in("resume_id", allResumeIds);
466→
467→            const resumeMap = new Map(allResumes.map((r: any) => [r.id, r]));
468→            const allMerged: Result[] = (resultData ?? []).map((r: any) => {
469→              const resume = resumeMap.get(r.resume_id);
470→              const parsed = resume?.parsed_json as any;
471→              return {
472→                ...r,
473→                overall_score: r.overall_score ?? 0,
474→                missing_skills: r.missing_skills ?? [],
475→                filename: resume?.filename ?? "Unknown",
476→                file_path: resume?.file_path ?? null,
477→                candidate_name: resume?.candidate_name ?? null,
478→                candidate_email: parsed?.email ?? parsed?.contact?.email ?? null,
479→                candidate_phone: parsed?.phone ?? parsed?.contact?.phone ?? null,
480→                candidate_location: parsed?.location ?? parsed?.contact?.location ?? null,
481→                parsed_json: resume?.parsed_json ?? null,
482→              };
483→            });
484→          // Deduplicate by resume_id — keep highest score
485→          const deduped = new Map<string, Result>();
486→          for (const r of allMerged) {
487→            const existing = deduped.get(r.resume_id);
488→            if (!existing || r.overall_score > existing.overall_score) {
489→              deduped.set(r.resume_id, r);
490→            }
491→          }
492→          const merged = Array.from(deduped.values());
493→          merged.sort((a, b) => b.overall_score - a.overall_score);
494→          setResults(merged);
495→        }
496→        setStuckJobDetected(false);
497→        setRankingProgress(100);
498→        await refreshProfile();
499→        setTimeout(() => { resultsRef.current?.scrollIntoView({ behavior: "smooth", block: "start" }); }, 200);

500→        return;
501→      }
502→      if (jobData?.status === "failed") throw new Error("Ranking failed on server");
503→    }
504→    throw new Error("Ranking timed out");
